def make_question(index, row):
    tag, prompt, options, answer, reason = row
    opts = [{"id": chr(65+i), "text": text} for i, text in enumerate(options)]
    aid = next(o["id"] for o in opts if o["text"] == answer)
    refs = [{"url": u, "title": f"{t}；僅研究公開題型與能力方向，未複製原題。", "year": "113-114", "subject": "social", "locator": l, "observedPattern": "公立學校社會科公開試題常見的流域、降雨、供需與水資源政策判讀能力，經本題重新設計。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for u,t,l in SOURCES]
    steps = [f"讀題定位：圈出「{tag}」的流域、月份、降雨、蓄水、用水與調度條件。", f"整理證據：分開水的來源、可用量、需求與制度分配；核心理由是「{reason}」。", f"核對正解：選項 {aid}「{answer}」同時符合水資源的空間與時間特性。", "排除誘答：檢查是否只看年雨量、名目容量、單一群體或單一水庫，並找出缺少的供需資料。", "結論回查：確認流域、月份、單位、有效容量與需求資料一致；情境改變時重新判讀。"]
    return {"id": f"question-social-content-geo-ac-iv-3-{index}", "subject": "social", "type": "single-choice", "prompt": prompt, "options": opts, "knowledgeIds": ["kg-social-content-geo-ac-iv-3"], "difficulty": "medium", "answer": {"value": aid, "explanation": reason}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0][0], "sourceLocator": "高雄市立鹽埕國中三年級社會科公開段考；本題只研究公開試題能力結構與資料型態。", "authoringNote": "依官方課綱、單元 KG 與三個公立學校公開來源的題型方向，獨立改寫水資源分布與供需調度情境；未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-09", "lessonId": "lesson-social-content-geo-ac-iv-3", "examPatternRefs": refs, "solutionStrategy": "先追蹤水從流域到住家的路徑，再分開降雨、蓄水、用水與水質，最後檢查空間、季節與調度公平。", "solutionSteps": steps}

